//! `RubyRandom` against vectors drawn from Ruby 3.3 itself
//! (tests/fixtures/ruby_random_vectors.json, generated by the scripts kept
//! in the cistergraphia repository's port notes).

use rustergraphia::RubyRandom;
use serde_json::Value;

fn vectors() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/ruby_random_vectors.json"
    );
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn ints(v: &Value, key: &str) -> Vec<i64> {
    v[key]
        .as_array()
        .unwrap_or_else(|| panic!("missing {key}"))
        .iter()
        .map(|n| n.as_i64().unwrap())
        .collect()
}

fn floats(v: &Value, key: &str) -> Vec<f64> {
    v[key]
        .as_array()
        .unwrap()
        .iter()
        .map(|n| n.as_f64().unwrap())
        .collect()
}

#[test]
fn small_seed_rand() {
    let v = vectors();
    let mut r = RubyRandom::new(42);
    let got: Vec<i64> = (0..20).map(|_| r.rand_below(100) as i64).collect();
    assert_eq!(got, ints(&v, "s42_rand100"));
}

#[test]
fn negative_seeds_use_the_absolute_value() {
    let v = vectors();
    for (seed, key) in [(-1, "sneg1_rand100"), (-6, "sneg6_rand100")] {
        let mut r = RubyRandom::new(seed);
        let got: Vec<i64> = (0..10).map(|_| r.rand_below(100) as i64).collect();
        assert_eq!(got, ints(&v, key), "seed {seed}");
    }
}

#[test]
fn bignum_seed_from_sha256() {
    let v = vectors();
    let hex = v["bignum_seed_hex"].as_str().unwrap();
    let bytes: Vec<u8> = (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
        .collect();
    let mut r = RubyRandom::from_be_bytes(&bytes);
    let got: Vec<i64> = (0..10).map(|_| r.rand_below(100) as i64).collect();
    assert_eq!(got, ints(&v, "bignum_rand100"));
}

#[test]
fn seeding_edge_cases() {
    let v = vectors();
    let cases: [(&str, &[u32]); 7] = [
        ("seed_p32", &[0, 1]),
        ("seed_p32p5", &[5, 1]),
        ("seed_p64", &[0, 0, 1]),
        ("seed_top1", &[5, 1]),
        ("seed_big_top1", &[9, 7, 1]),
        ("seed_zero", &[0]),
        ("seed_words05", &[5]),
    ];
    for (key, words) in cases {
        let mut r = RubyRandom::from_words(words);
        let got: Vec<i64> = (0..10).map(|_| r.rand_below(1000) as i64).collect();
        assert_eq!(got, ints(&v, key), "{key}");
    }
}

#[test]
fn float_draws() {
    let v = vectors();
    let mut r = RubyRandom::new(7);
    let got: Vec<f64> = (0..10).map(|_| r.rand_float()).collect();
    assert_eq!(got, floats(&v, "s7_float"));

    let mut r = RubyRandom::new(7);
    let got: Vec<f64> = (0..10).map(|_| r.rand_float_incl(-1.0, 1.0)).collect();
    assert_eq!(got, floats(&v, "s7_frange"));
}

#[test]
fn integer_ranges() {
    let v = vectors();
    let mut r = RubyRandom::new(7);
    let got: Vec<i64> = (0..10).map(|_| r.rand_int_incl(-3, 3)).collect();
    assert_eq!(got, ints(&v, "s7_irange"));

    let mut r = RubyRandom::new(7);
    let got: Vec<i64> = (0..10).map(|_| r.rand_int_incl(0, 5)).collect();
    assert_eq!(got, ints(&v, "s7_r0to5"));
}

#[test]
fn shuffle_and_sample() {
    let v = vectors();
    let mut r = RubyRandom::new(9);
    let mut items: Vec<i64> = (0..10).collect();
    r.shuffle(&mut items);
    assert_eq!(items, ints(&v, "s9_shuffle"));

    let mut r = RubyRandom::new(9);
    let pool = [10i64, 20, 30, 40];
    let got: Vec<i64> = (0..10).map(|_| pool[r.sample_index(pool.len())]).collect();
    assert_eq!(got, ints(&v, "s9_sample1"));

    let mut r = RubyRandom::new(9);
    for row in v["s9_sample2"].as_array().unwrap() {
        let want: Vec<i64> = row.iter_array();
        let got: Vec<i64> = r
            .sample_indices(3, 10)
            .into_iter()
            .map(|i| i as i64)
            .collect();
        assert_eq!(got, want);
    }
}

trait RowExt {
    fn iter_array(&self) -> Vec<i64>;
}

impl RowExt for Value {
    fn iter_array(&self) -> Vec<i64> {
        self.as_array()
            .unwrap()
            .iter()
            .map(|n| n.as_i64().unwrap())
            .collect()
    }
}

#[test]
fn large_bounds_and_bytes() {
    let v = vectors();
    let mut r = RubyRandom::new(5);
    let got: Vec<i64> = (0..10).map(|_| r.rand_below(9999) as i64).collect();
    assert_eq!(got, ints(&v, "s5_rand9999"));

    let mut r = RubyRandom::new(5);
    let got: Vec<i64> = (0..10).map(|_| r.rand_below(2) as i64).collect();
    assert_eq!(got, ints(&v, "s5_rand2"));

    let mut r = RubyRandom::new(42);
    assert_eq!(
        hex(&r.bytes(16)),
        v["s42_bytes16"].as_array().unwrap()[0].as_str().unwrap()
    );

    let mut r = RubyRandom::new(3);
    assert_eq!(hex(&r.bytes(7)), v["s3_bytes7"].as_str().unwrap());

    let pair = v["s3_bytes3_then_rand"].as_array().unwrap();
    let mut r = RubyRandom::new(3);
    assert_eq!(hex(&r.bytes(3)), pair[0].as_str().unwrap());
    assert_eq!(
        r.rand_below(100).to_string(),
        pair[1].as_str().unwrap().to_string()
    );
}

#[test]
fn mixed_stream() {
    let v = vectors();
    let want: Vec<String> = v["s11_mixed"]
        .as_array()
        .unwrap()
        .iter()
        .map(|s| s.as_str().unwrap().to_string())
        .collect();
    let mut r = RubyRandom::new(11);
    let got = [
        r.rand_below(100).to_string(),
        format!("{}", r.rand_float()),
        r.rand_below(1000).to_string(),
        format!("{}", r.rand_float()),
        r.rand_int_incl(-3, 3).to_string(),
    ];
    assert_eq!(got.to_vec(), want);
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}
